from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class DistNamesSlot(SchemaObject):
    config = SchemaField(name="config")
    runtime = SchemaField(name="runtime")

    def __init__(self, config, runtime):
        self.config = config
        self.runtime = runtime
        super(DistNamesSlot, self).__init__()


class Alarm(SchemaObject):
    uuid = SchemaField(name="uuid", not_null=True)
    severity = SchemaField(name="severity", not_null=True)
    alarm_id = SchemaField(name="alarm_id", not_null=True)
    alarm_name = SchemaField(name="alarm_name", not_null=True)
    fault_id = SchemaField(name="fault_id", not_null=True)
    fault_name = SchemaField(name="fault_name", not_null=True)

    def __init__(self, uuid, severity, alarm_id, alarm_name, fault_id, fault_name):
        self.uuid = uuid
        self.severity = severity
        self.alarm_id = alarm_id
        self.alarm_name = alarm_name
        self.fault_id = fault_id
        self.fault_name = fault_name

        super(Alarm, self).__init__()


class XnLinkSlot(SchemaObject):
    xn_link_id = SchemaField(name="xn_link_id", not_null=True)
    xn_link_status = SchemaField(name="xn_link_status", not_null=True)
    c_plane_ip_addr_ctrl = SchemaField(name="c_plane_ip_addr_ctrl", not_null=True)
    c_plane_ip_addr = SchemaField(name="c_plane_ip_addr", not_null=True)
    alarms = SchemaField(name="alarms", klass=Alarm, many=True, not_null=True)
    dist_names = SchemaField(name="dist_names", klass=DistNamesSlot, not_null=True)
    administrative_state = SchemaField(name="administrative_state", not_null=True)
    nr_adj_gnb_id = SchemaField(name="nr_adj_gnb_id")
    xn_tnl_id = SchemaField(name="xn_tnl_id")
    is_second_xn_link = SchemaField(name="is_second_xn_link")

    def __init__(self, xn_link_id, xn_link_status, c_plane_ip_addr_ctrl, c_plane_ip_addr, alarms, dist_names,
                 administrative_state, nr_adj_gnb_id, xn_tnl_id, is_second_xn_link):
        self.xn_link_id = xn_link_id
        self.xn_link_status = xn_link_status
        self.c_plane_ip_addr_ctrl = c_plane_ip_addr_ctrl
        self.c_plane_ip_addr = c_plane_ip_addr
        self.administrative_state = administrative_state
        self.nr_adj_gnb_id = nr_adj_gnb_id
        self.xn_tnl_id = xn_tnl_id
        self.is_second_xn_link = is_second_xn_link
        self.alarms = alarms
        self.dist_names = dist_names

        super(XnLinkSlot, self).__init__()


class XnLinksDiffResponseASMV1(SchemaObject):
    revision = SchemaField(name="revision", not_null=True)
    created = SchemaField(name="created", not_null=True, klass=XnLinkSlot, many=True)
    updated = SchemaField(name="updated", not_null=True, klass=XnLinkSlot, many=True)
    removed = SchemaField(name="removed", not_null=True, many=True)

    def __init__(self, revision, created, updated, removed):
        self.revision = revision
        self.created = created
        self.updated = updated
        self.removed = removed

        super(XnLinksDiffResponseASMV1, self).__init__()
